const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const searchLink=k=>'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(places[k].q);
const ext=(url,label,cls='')=>`<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`;
const placeLink=(k,label)=>ext(searchLink(k),esc(label||places[k].name));
let map=null,routeOrigin='hotel';
function directionLink(origin,dest,mode='transit'){return 'https://www.google.com/maps/dir/?api=1&origin='+encodeURIComponent(places[origin].q)+'&destination='+encodeURIComponent(places[dest].q)+'&travelmode='+mode;}
function routeLinks(d){const dest=d.meetKey||d.stops.find(k=>k!=='hotel'&&k!=='airport')|| (d.id===13?'hotel':'airport');const origin=d.shared?routeOrigin:(d.id===13?'airport':'hotel');return ext(directionLink(origin,dest,d.shared?'transit':'driving'),d.shared?'Ruta hasta el encuentro':'Abrir traslado inicial','button');}
function render(){const id=Number(location.hash.match(/^#dia-(\d+)$/)?.[1]||13);const d=days.find(x=>x.id===id)||days[0];document.querySelectorAll('#days a').forEach(a=>{const on=a.hash==='#dia-'+d.id;a.classList.toggle('selected',on);if(on)a.setAttribute('aria-current','date');else a.removeAttribute('aria-current');});if(map){map.remove();map=null;}
$('#day-content').innerHTML=`<div class="day-heading"><div><p class="eyebrow">${d.week} ${d.id} de octubre · ${d.tag}</p><h2>${d.title}</h2></div><div class="weather"><b>63–77 °F <span class="rain-value">☂ ≈85%</span></b><span>Medellín · referencia histórica de octubre</span><a href="#clima">No es un pronóstico diario</a></div></div><div class="day-meta"><span>${d.zone}</span><span>Hora de Colombia · UTC−5</span></div><p class="day-intro">${d.intro}</p>${d.shared?`<div class="meeting"><div><span class="eyebrow">PUNTO DE ENCUENTRO</span><h3>${d.meet}</h3>${placeLink(d.meetKey,'Ver estación')}</div><div><b>H · Rafy y Vanessa</b><p>${d.fromH}</p></div><div><b>B · Germán y Lina</b><p>${d.fromB}</p></div></div>`:''}<div class="layout"><div><article class="panel timeline"><p class="eyebrow">EL DÍA, PASO A PASO</p>${d.events.map(([time,title,desc,k])=>`<div class="event"><time>${time}</time><div><h4>${title}</h4><p>${desc}</p>${k?placeLink(k,'Ubicación'):''}</div></div>`).join('')}</article><section class="dinner panel"><p class="eyebrow">${d.id===20?'ANTES DEL VUELO':'A LA HORA DE CENAR'}</p><h3>${d.dinner.title}</h3><p>${d.dinner.desc}</p>${d.dinner.options.map(([key,label,rating])=>`<div class="restaurant"><div>${placeLink(key,label)}${rating?'<small>Puntuación histórica de la guía</small>':''}</div>${rating?`<strong>★ ${rating}</strong>`:''}</div>`).join('')}${d.dinner.options.some(x=>x[2])?'<p class="fine">Valores de las guías aportadas (septiembre de 2026); plataforma no identificada. No son valoraciones verificadas en tiempo real. <a href="#fuentes">Ver criterio</a>.</p>':''}</section></div><aside class="side"><section class="panel map-panel"><div class="map-title"><div><p class="eyebrow">MAPA DEL ${d.id} DE OCTUBRE</p><h3>${d.shared?'Dos bases. Un mismo plan.':d.id===13?'Del aeropuerto al Hampton.':'Tu ruta desde el Hampton.'}</h3></div><button id="fit-map" aria-label="Mostrar todos los puntos del día">⤢</button></div><div id="map" role="region" aria-label="Mapa interactivo del itinerario del ${d.id} de octubre"></div><div class="legend"><span><i class="hotel-dot"></i>Hampton</span>${d.shared?'<span><i class="base-dot"></i>Bicentenario</span>':''}<span><i class="stop-dot"></i>Visitas</span><span><i class="food-dot"></i>Cena</span></div><p class="fine">Puntos de orientación y orden de visita; la línea punteada no representa calles ni un trayecto navegable. ${d.shared?'Bicentenario es la estación de referencia, no la puerta del Airbnb.':''}</p>${d.shared?'<div class="origin-switch" aria-label="Elegir alojamiento de salida"><button data-origin="hotel">Desde el Hampton</button><button data-origin="bicentenario">Desde Bicentenario</button></div>':''}<div id="route-link">${routeLinks(d)}</div><div class="stops">${d.stops.map((k,i)=>`<div><span>${i+1}</span>${placeLink(k)}</div>`).join('')}</div></section>${d.image?`<figure class="family-day"><img src="assets/${d.image}" alt="${esc(d.imageAlt)}" loading="lazy" width="1672" height="941"><figcaption>Así imaginamos el viaje de los cuatro · Recreación con IA a partir de sus fotos.</figcaption></figure>`:''}<section class="panel practical-day"><h3>Antes de salir</h3><p><b>Cómo moverse</b><br>${d.transport}</p><p><b>Si llueve</b><br>${d.rain}</p><p><b>En la mochila</b><br>${d.pack}</p>${d.note?`<div class="note">${d.note}</div>`:''}</section></aside></div><div class="day-bottom">${d.id>13?`<a href="#dia-${d.id-1}" class="button light">← Día anterior</a>`:'<span></span>'}${d.id<20?`<a href="#dia-${d.id+1}" class="button">${d.id+1} de octubre →</a>`:'<a href="#dia-13" class="button">Volver al comienzo ↑</a>'}</div>`;
renderMap(d);document.querySelectorAll('[data-origin]').forEach(b=>{b.classList.toggle('active',b.dataset.origin===routeOrigin);b.onclick=()=>{routeOrigin=b.dataset.origin;document.querySelectorAll('[data-origin]').forEach(x=>x.classList.toggle('active',x.dataset.origin===routeOrigin));$('#route-link').innerHTML=routeLinks(d);};});
}
function renderMap(d){if(!window.L){$('#map').innerHTML='<p class="map-error">No se pudo cargar el mapa. Los enlaces de ubicación y traslado siguen disponibles abajo.</p>';return;}map=L.map('map',{scrollWheelZoom:false}).setView(places.hotel.p,12);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).addTo(map);let failed=false;map.eachLayer(l=>l.on&&l.on('tileerror',()=>{if(!failed){failed=true;const e=document.createElement('p');e.className='fine';e.textContent='La cartografía no está disponible. Puedes usar los enlaces de navegación debajo del mapa.';$('#map').after(e);}}));const points=[];const icon=(text,type)=>L.divIcon({className:'map-pin '+type,html:`<span>${text}</span>`,iconSize:[32,32],iconAnchor:[16,16]});function marker(k,label,type){const p=places[k];points.push(p.p);L.marker(p.p,{icon:icon(label,type),title:p.name}).addTo(map).bindPopup(`<b>${esc(p.name)}</b>${p.note?'<p>'+esc(p.note)+'</p>':''}<p>${placeLink(k,'Abrir ubicación')}</p>`);}marker('hotel','H','hotel');if(d.shared)marker('bicentenario','B','base');d.stops.forEach((k,i)=>{if(k!=='hotel')marker(k,i+1,'stop');});d.dinner.options.filter(([k])=>!d.stops.includes(k)&&k!=='hotel').forEach(([k])=>marker(k,'♧','food'));const seq=d.id===13?d.stops:['hotel',...d.stops.filter(k=>k!=='hotel')];L.polyline(seq.map(k=>places[k].p),{color:'#668256',weight:2,dashArray:'5 7',opacity:.7}).addTo(map);if(d.shared)L.polyline([places.bicentenario.p,places[d.meetKey].p],{color:'#a65b36',weight:2,dashArray:'5 7'}).addTo(map);const fit=()=>map.fitBounds(points,{padding:[35,35],maxZoom:15});fit();$('#fit-map').onclick=fit;}
$('#bases').innerHTML=`<div class="section-heading"><p class="eyebrow">EL PUNTO DE PARTIDA</p><h2>Dos direcciones, cuatro viajeros.</h2></div><div class="base-grid"><article class="base-card"><span class="base-letter">H</span><div><p class="eyebrow">RAFY & VANESSA · 13–20 OCT</p><h3>Hampton by Hilton</h3><p>Calle 6 Sur #42-14, El Poblado.<br>Sector Oviedo / Santafé.</p><p>Aguacatala es una conexión al metro en taxi, aproximadamente 10–20 min. No está al lado del hotel; consultar en recepción si conviene más salir por Poblado.</p>${placeLink('hotel','Cómo llegar al Hampton')}</div></article><article class="base-card"><span class="base-letter copper">B</span><div><p class="eyebrow">GERMÁN & LINA · DESDE EL VIERNES 16</p><h3>Cerca de Bicentenario</h3><p>Airbnb en el entorno de la estación del tranvía.<br>La dirección exacta está por incorporar.</p><p>La estación permite conectar con San Antonio mediante el T-A. Coordinar la caminata desde el alojamiento una vez recibido el pin del anfitrión.</p>${placeLink('bicentenario','Ver estación Bicentenario')}</div></article></div>`;
$('#gallery').innerHTML=`<div class="section-heading"><p class="eyebrow">EL ÁLBUM QUE VIENE</p><h2>Ya nos imaginamos allí.</h2><p>Tres escenas creadas con sus fotografías. Son recreaciones con IA de un viaje futuro, no fotos documentales ni una reproducción exacta de los lugares.</p></div><div class="gallery-grid"><figure><img src="assets/comuna-family.jpg" alt="Recreación de los cuatro viajeros en Comuna 13" loading="lazy" width="1672" height="941"><figcaption><b>Sábado · Comuna 13</b><span>Arte urbano y un reencuentro a todo color.</span></figcaption></figure><figure><img src="assets/arvi-family.jpg" alt="Recreación de los cuatro viajeros en Parque Arví" loading="lazy" width="1672" height="941"><figcaption><b>Domingo · Parque Arví</b><span>Un respiro entre montañas y bosque.</span></figcaption></figure><figure><img src="assets/botero-family.jpg" alt="Recreación imaginada de las dos parejas con esculturas en Plaza Botero" loading="lazy" width="1672" height="941"><figcaption><b>La foto soñada · Plaza Botero</b><span>Escena imaginada de los cuatro. La visita del plan sigue el miércoles con Rafy y Vanessa; no añade un traslado al fin de semana.</span></figcaption></figure></div>`;
$('#practical').innerHTML=`<div class="section-heading"><p class="eyebrow">LOS DETALLES QUE AYUDAN</p><h2>Listos para disfrutar.</h2></div><div class="info-grid"><details open id="clima"><summary>Temperatura y lluvia: cómo leerlas</summary><p>Referencia de octubre para Medellín: mínima típica de 63 °F, máxima de 77 °F y alrededor del 85% de días con al menos 0.04 pulgadas (aprox. 1 mm) de precipitación. Es frecuencia histórica, no lluvia durante el 85% del día.</p><p>Repetimos la referencia mensual en los ocho días para no inventar diferencias entre fechas. No es un pronóstico para octubre de 2026 ni una estimación específica de Arví, que se encuentra a mayor altura. Revisar el pronóstico local 5–7 días antes y cada mañana.</p>${ext('https://weatherspark.com/m/22535/10/Average-Weather-in-October-in-Medell%C3%ADn-Colombia','Datos de Weather Spark')}</details><details open><summary>Lo que conviene dejar coordinado</summary><ul><li>Traslados de llegada y recogida del martes a las 6:30 a. m.; confirmar MDE en el billete.</li><li>Comprobante de Andrés para el viernes a las 7 p. m.</li><li>Dirección del Airbnb y encuentro de San Antonio para sábado y domingo.</li><li>Guía de Comuna 13 y su punto exacto de inicio.</li><li>Estado del cable, tarifas del tramo L y sendero en Arví.</li><li>Operación del Mercado del Tranvía antes de ir.</li><li>Pin, condiciones de entrada, mesa y conductor de regreso para La Octava Maravilla.</li><li>Hora de regreso de Germán y Lina a Manizales, aún sin definir.</li></ul></details><details id="fuentes"><summary>Fuentes, criterios y fotografías</summary><p>Plan principal: <em>Medellin_13-20_octubre_2026.pdf</em>, aportado por ustedes. El dossier de aniversario y las otras tres guías visuales/generales sirven de contexto. Se priorizan el calendario correcto de 2026 y sus nuevas indicaciones: Germán y Lina llegan el viernes por la noche, temperaturas en Fahrenheit y vuelos a las 6:25 p. m. / 11 a. m.</p><p>Las puntuaciones de restaurantes se transcriben de las guías anteriores, fechadas en septiembre de 2026, sin atribuirlas a una plataforma no identificada. Se ordenan de mayor a menor dentro de las opciones de cada noche cuando existen datos comparables. No implican disponibilidad ni reserva.</p><p>Horarios y trayectos son propuestas. Las coordenadas son orientativas; Hampton y La Octava se contrastaron con Waze, y los demás puntos ubican los sectores. Las líneas dibujadas no son rutas calculadas. Cartografía © OpenStreetMap.</p><p>Revisión de páginas operativas: 19 de septiembre de 2026.</p><ul>${[
['Hampton · dirección y servicios','https://www.hilton.com/es/hotels/mdehxhx-hampton-medellin/hotel-info/'],['Catedral Metropolitana','https://arqmedellin.co/parroquias/la-catedral/'],['Pueblito Paisa · Medellín Travel','https://www.medellin.travel/pueblito-paisa-cerro-nutibara/'],['Mercado del Río · horarios','https://mercadodelrio.com.co/'],['Andrés Medellín','https://www.andrescarnederes.com/andres-medellin'],['Café Cliché · dirección en Laureles','https://www.cafeclichemedellin.com/domicilios'],['Metro · línea L, horario dominical','https://www.metrodemedellin.gov.co/usuarios/sistema-integrado/linea-l'],['Parque Arví','https://parquearvi.org/corporacion/'],['Mercado del Tranvía · ficha de referencia, operación por confirmar','https://www.tripadvisor.es/Restaurant_Review-g297478-d13341660-Reviews-Mercado_Del_Tranvia-Medellin_Antioquia_Department.html'],['La Octava Maravilla · carta y horario','https://eslacarta.com/laoctavamaravilla/'],['La Octava · reservas y acceso','https://lnk.bio/OctavaMaravilla'],['La Octava · pin de Waze','https://www.waze.com/es/live-map/directions/restaurante-la-octava-maravilla-calle-62-sur-sabaneta?to=place.w.186384445.1863778918.14297113']].map(([t,u])=>'<li>'+ext(u,t)+'</li>').join('')}</ul><p>Panorámica de Medellín: ${ext('https://commons.wikimedia.org/wiki/File:Medell%C3%ADn_Panor%C3%A1mica.jpg','Carlos Andres Granada')} · ${ext('https://creativecommons.org/licenses/by-sa/4.0/','CC BY-SA 4.0')}; encuadre recortado en pantalla. Las tres escenas familiares son imágenes generadas con IA a partir de las fotos facilitadas por ustedes.</p></details></div>`;
window.addEventListener('hashchange',()=>{if(/^#dia-\d+$/.test(location.hash)){render();$('#day-content').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}});render();
